var shapes = [];
var shapesNum = 80;
var maxR;

function setup() {
  createCanvas(650, 650);
  colorMode(HSB, 360, 100, 100, 100);
  rectMode(CENTER);
  angleMode(DEGREES);
  textAlign(CENTER, CENTER);

  maxR = max(width, height) * 0.8;
  noStroke();

  for (let i = 0; i < shapesNum; i++) {
    shapes.push(new Shape());
  }
  background(0);
}

function draw() {
  blendMode(BLEND);
  background(0, 0, 0, 30);

  // blendMode(SCREEN);
  for (let i = 0; i < shapes.length; i++) {
    shapes[i].move();
    shapes[i].display();
  }

  filter(BLUR, 6);
  filter(POSTERIZE, 4);
}

class Shape {
  constructor() {
    this.isEmoji = random(1) < 0.2 ? true : false;
    this.x = width / 2;
    this.y = height / 2;
    this.r = random(maxR);
    this.startT = random(-180 + 45, -45);
    this.t = this.startT;
    this.rSpeed = random(0.5, 1) * 10;
    this.tSpeed = random(0, 0.75);
    this.maxW = this.isEmoji ? random(10, 150) : random(10, 200);
    this.w = this.maxW;
    this.c = color(random(170, 240), 100, 100, 50);
    this.n = random(1000);
  }

  move() {
    this.x = width / 2 + cos(this.t) * this.r;
    this.y = height * 0.8 + sin(this.t) * this.r;
    this.r += this.rSpeed;
    this.w = map(this.r, 0, maxR, this.maxW, 0);
    this.t = map(noise(frameCount * 0.01, this.n), 0, 1, -180 + 45, -45);
    //this.startT + map(noise(frameCount * 0.0075), 0, 1, -15, 15);

    if (this.r > maxR) {
      this.r = 0;
    }
  }

  display() {
    fill(this.c);
    push();
    translate(this.x, this.y);
    // rotate(this.t + 45);
    if (this.isEmoji) {
      textSize(this.w);
      text("👻", 0, 0);
    } else {
      circle(0, 0, this.w);
    }
    pop();
  }
}
